package config

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"os"
	"regexp"
	"strings"
	"time"
)

var (
	reIfaceName = regexp.MustCompile(`^[A-Za-z0-9_.-]{1,15}$`)
	reDigits    = regexp.MustCompile(`^[0-9]+$`)
)

// Config represents the per-SIM JSON configuration generated by RootIdentityMain.
type Config struct {
	Enabled   bool   `json:"enabled"`
	Transport string `json:"transport"`
	Slot      int    `json:"slot"`
	ICCID     string `json:"iccid"`
	MCC       string `json:"mcc"`
	MNC       string `json:"mnc"`
	MNCLen    int    `json:"mncLen"`
	IMSRealm  string `json:"imsRealm"`
	EPDG      string `json:"epdgFqdn"`
	DNS       string `json:"dns"`
	SMSC      string `json:"smsc"`
	CarrierID int    `json:"carrierId,omitempty"`
	IMSI                  string `json:"imsi"`
	IMEI                  string `json:"imei"`
	IMPI                  string `json:"impi,omitempty"`
	IMPU                  string `json:"impu,omitempty"`
	SIPIMPU               string `json:"sipImpu,omitempty"`
	IMSHomeDomain         string `json:"imsHomeDomain,omitempty"`
	IMSIdentityMode       string `json:"imsIdentityMode,omitempty"`
	IMSIdentityReadStatus string `json:"imsIdentityReadStatus,omitempty"`
	// Optional overrides for testing or custom carrier profiles.
	EPDGAddr string `json:"epdgAddr,omitempty"`
	SimMode  string `json:"simMode,omitempty"`
}

// ValidationError carries a stable machine-readable code for RootIdentityMain.
type ValidationError struct {
	Code    string
	Message string
}

func (e *ValidationError) Error() string {
	return e.Code + ": " + e.Message
}

func LoadFile(path string) (*Config, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, &ValidationError{Code: "CONFIG_READ_FAILED", Message: err.Error()}
	}
	return ParseJSON(raw)
}

func ParseJSON(raw []byte) (*Config, error) {
	raw = bytes.TrimPrefix(raw, []byte{0xEF, 0xBB, 0xBF})
	var cfg Config
	dec := json.NewDecoder(bytes.NewReader(raw))
	if err := dec.Decode(&cfg); err != nil {
		return nil, &ValidationError{Code: "CONFIG_JSON_INVALID", Message: err.Error()}
	}
	return &cfg, nil
}

// InterfaceName extracts <name> from transport "iface:<name>".
func (c *Config) InterfaceName() (string, error) {
	if !strings.HasPrefix(c.Transport, "iface:") {
		return "", &ValidationError{Code: "TRANSPORT_INVALID", Message: "transport must start with iface:"}
	}
	name := strings.TrimPrefix(c.Transport, "iface:")
	if !reIfaceName.MatchString(name) {
		return "", &ValidationError{Code: "TRANSPORT_INVALID", Message: "invalid interface name"}
	}
	return name, nil
}

// PadMNC3 returns the 3-digit zero-padded MNC used by 3GPP realm/FQDN formats.
func PadMNC3(mnc string) string {
	if len(mnc) == 2 {
		return "0" + mnc
	}
	return mnc
}

// DeriveIMSRealm computes ims.mnc<MNC3>.mcc<MCC>.3gppnetwork.org.
func DeriveIMSRealm(mcc, mnc string) string {
	return fmt.Sprintf("ims.mnc%s.mcc%s.3gppnetwork.org", PadMNC3(mnc), mcc)
}

// DeriveEPDGFQDN computes epdg.epc.mnc<MNC3>.mcc<MCC>.pub.3gppnetwork.org.
func DeriveEPDGFQDN(mcc, mnc string) string {
	return fmt.Sprintf("epdg.epc.mnc%s.mcc%s.pub.3gppnetwork.org", PadMNC3(mnc), mcc)
}

// EffectiveEPDG returns explicit epdgFqdn, carrier-registry override, or derived 3GPP FQDN.
func (c *Config) EffectiveEPDG() string {
	if strings.TrimSpace(c.EPDG) != "" {
		return strings.TrimSpace(c.EPDG)
	}
	if hint, ok := LookupCarrierHint(c.MCC, c.MNC); ok && hint.EPDGFQDN != "" {
		return hint.EPDGFQDN
	}
	return DeriveEPDGFQDN(c.MCC, c.MNC)
}

// EffectiveIMPI returns explicit IMPI or 3GPP TS 23.003 derived IMPI from IMSI.
func (c *Config) EffectiveIMPI() string {
	if strings.TrimSpace(c.IMPI) != "" {
		return strings.TrimSpace(c.IMPI)
	}
	return fmt.Sprintf("%s@%s", c.IMSI, c.IMSRealm)
}

// EffectiveIMPU returns explicit ISIM sipImpu/impu or 3GPP TS 23.003 temporary public identity.
func (c *Config) EffectiveIMPU() string {
	if strings.TrimSpace(c.SIPIMPU) != "" {
		return strings.TrimSpace(c.SIPIMPU)
	}
	if strings.TrimSpace(c.IMPU) != "" {
		return strings.TrimSpace(c.IMPU)
	}
	return fmt.Sprintf("sip:%s@%s", c.IMSI, c.IMSRealm)
}

// EffectiveEAPIdentity returns the 3GPP NAI identity for EAP-AKA / EAP-AKA' (0<IMSI>@wlan...).
func (c *Config) EffectiveEAPIdentity() string {
	return fmt.Sprintf("0%s@wlan.mnc%s.mcc%s.3gppnetwork.org", c.IMSI, PadMNC3(c.MNC), c.MCC)
}

// Validate checks all strict invariants required by RootIdentityMain config-verify --strict.
func (c *Config) Validate(strict bool) error {
	if !c.Enabled {
		return &ValidationError{Code: "CONFIG_DISABLED", Message: "enabled must be true"}
	}
	if _, err := c.InterfaceName(); err != nil {
		return err
	}
	if c.Slot < 0 || c.Slot > 7 {
		return &ValidationError{Code: "INVALID_SLOT", Message: "slot out of range"}
	}
	if len(c.ICCID) < 10 || len(c.ICCID) > 32 || !reDigits.MatchString(c.ICCID) {
		return &ValidationError{Code: "INVALID_ICCID", Message: "iccid must be 10-32 digits"}
	}
	if len(c.MCC) != 3 || !reDigits.MatchString(c.MCC) {
		return &ValidationError{Code: "INVALID_MCC", Message: "mcc must be 3 digits"}
	}
	if (len(c.MNC) != 2 && len(c.MNC) != 3) || !reDigits.MatchString(c.MNC) {
		return &ValidationError{Code: "INVALID_MNC", Message: "mnc must be 2 or 3 digits"}
	}
	if c.MNCLen != len(c.MNC) {
		return &ValidationError{Code: "MNC_LENGTH_MISMATCH", Message: "mncLen does not match mnc"}
	}
	if strict && (c.MCC == "460" || c.MCC == "461") {
		return &ValidationError{Code: "MAINLAND_SIM_FORBIDDEN", Message: "mainland SIM excluded"}
	}
	expectedRealm := DeriveIMSRealm(c.MCC, c.MNC)
	if c.IMSRealm != expectedRealm {
		return &ValidationError{Code: "IMS_REALM_MISMATCH", Message: "imsRealm does not match mcc/mnc"}
	}
	if len(c.IMSI) != 15 || !reDigits.MatchString(c.IMSI) {
		return &ValidationError{Code: "INVALID_IMSI", Message: "imsi must be 15 digits"}
	}
	if !strings.HasPrefix(c.IMSI, c.MCC+c.MNC) {
		return &ValidationError{Code: "IMSI_PLMN_MISMATCH", Message: "imsi does not start with home PLMN"}
	}
	if len(c.IMEI) != 15 || !reDigits.MatchString(c.IMEI) {
		return &ValidationError{Code: "INVALID_IMEI", Message: "imei must be 15 digits"}
	}
	if c.DNS != "" {
		host := strings.TrimSpace(c.DNS)
		if h, _, err := net.SplitHostPort(host); err == nil {
			host = h
		}
		if net.ParseIP(host) == nil {
			return &ValidationError{Code: "INVALID_DNS", Message: "dns must be a valid IP literal"}
		}
	}
	return nil
}

// SanitizedMap returns a safe representation for rpc.getConfig with secrets masked as [Hidden].
func (c *Config) SanitizedMap() map[string]any {
	iface, _ := c.InterfaceName()
	return map[string]any{
		"enabled":   c.Enabled,
		"transport": c.Transport,
		"interface": iface,
		"slot":      c.Slot,
		"mcc":       c.MCC,
		"mnc":       c.MNC,
		"mncLen":    c.MNCLen,
		"imsRealm":  c.IMSRealm,
		"epdgFqdn":  c.EffectiveEPDG(),
		"dns":       c.DNS,
		"carrierId": c.CarrierID,
		"iccid":     "[Hidden]",
		"imsi":      "[Hidden]",
		"imei":      "[Hidden]",
	}
}

// ResolveHostIPv4 resolves host via explicit UDP DNS server (e.g. 1.1.1.1:53 inside isolated netns)
// so DNS never leaks to Android's root-netns netd. Falls back to system resolver when dnsServer is empty.
func ResolveHostIPv4(ctx context.Context, host, dnsServer string) (net.IP, error) {
	if ip := net.ParseIP(strings.TrimSpace(host)); ip != nil {
		if v4 := ip.To4(); v4 != nil {
			return v4, nil
		}
		return ip, nil
	}
	if strings.TrimSpace(dnsServer) == "" {
		addrs, err := net.DefaultResolver.LookupIPAddr(ctx, host)
		if err != nil {
			return nil, err
		}
		for _, a := range addrs {
			if v4 := a.IP.To4(); v4 != nil {
				return v4, nil
			}
		}
		if len(addrs) > 0 {
			return addrs[0].IP, nil
		}
		return nil, errors.New("DNS_NO_RECORD")
	}
	dnsTarget := dnsServer
	if _, _, err := net.SplitHostPort(dnsTarget); err != nil {
		dnsTarget = net.JoinHostPort(dnsServer, "53")
	}
	return resolveAOverUDP(ctx, host, dnsTarget)
}

func resolveAOverUDP(ctx context.Context, host, dnsAddr string) (net.IP, error) {
	var tx [2]byte
	_, _ = rand.Read(tx[:])
	txID := binary.BigEndian.Uint16(tx[:])

	var q bytes.Buffer
	q.Write(tx[:])
	q.Write([]byte{0x01, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00})
	for _, label := range strings.Split(strings.TrimSuffix(host, "."), ".") {
		if len(label) == 0 || len(label) > 63 {
			return nil, errors.New("DNS_INVALID_HOST")
		}
		q.WriteByte(byte(len(label)))
		q.WriteString(label)
	}
	q.Write([]byte{0x00, 0x00, 0x01, 0x00, 0x01}) // root, QTYPE=A, QCLASS=IN

	dialer := net.Dialer{Timeout: 5 * time.Second}
	conn, err := dialer.DialContext(ctx, "udp", dnsAddr)
	if err != nil {
		return nil, err
	}
	defer conn.Close()
	deadline, ok := ctx.Deadline()
	if !ok {
		deadline = time.Now().Add(5 * time.Second)
	}
	_ = conn.SetDeadline(deadline)

	if _, err := conn.Write(q.Bytes()); err != nil {
		return nil, err
	}
	buf := make([]byte, 1500)
	n, err := conn.Read(buf)
	if err != nil {
		return nil, err
	}
	if n < 12 {
		return nil, errors.New("DNS_RESPONSE_SHORT")
	}
	if binary.BigEndian.Uint16(buf[0:2]) != txID {
		return nil, errors.New("DNS_TXID_MISMATCH")
	}
	if rcode := buf[3] & 0x0F; rcode != 0 {
		return nil, fmt.Errorf("DNS_RCODE_%d", rcode)
	}
	qd := int(binary.BigEndian.Uint16(buf[4:6]))
	an := int(binary.BigEndian.Uint16(buf[6:8]))
	off := 12
	for i := 0; i < qd; i++ {
		off, err = skipDNSName(buf, off, n)
		if err != nil {
			return nil, err
		}
		off += 4
		if off > n {
			return nil, errors.New("DNS_PARSE_ERROR")
		}
	}
	for i := 0; i < an; i++ {
		off, err = skipDNSName(buf, off, n)
		if err != nil {
			return nil, err
		}
		if off+10 > n {
			return nil, errors.New("DNS_PARSE_ERROR")
		}
		rtype := binary.BigEndian.Uint16(buf[off : off+2])
		rclass := binary.BigEndian.Uint16(buf[off+2 : off+4])
		rdlen := int(binary.BigEndian.Uint16(buf[off+8 : off+10]))
		off += 10
		if off+rdlen > n {
			return nil, errors.New("DNS_PARSE_ERROR")
		}
		if rtype == 1 && rclass == 1 && rdlen == 4 {
			ip := make(net.IP, 4)
			copy(ip, buf[off:off+4])
			return ip, nil
		}
		off += rdlen
	}
	return nil, errors.New("DNS_NO_A_RECORD")
}

func skipDNSName(buf []byte, off, limit int) (int, error) {
	for guard := 0; off < limit && guard < 128; guard++ {
		b := buf[off]
		if b == 0 {
			return off + 1, nil
		}
		if (b & 0xC0) == 0xC0 {
			if off+2 > limit {
				return 0, errors.New("DNS_PARSE_ERROR")
			}
			return off + 2, nil
		}
		off += 1 + int(b)
	}
	return 0, errors.New("DNS_PARSE_ERROR")
}
